effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     vec2 project(vec2 a, vec2 b) {
         return (dot(a,b)/dot(b,b)) * b;
     }

     float smoothstepRev(float edge0, float edge1, float x) {
         if(edge0 == edge1) return step(edge0, x);
         else return smoothstep(edge0, edge1, x);
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);

     /////////////////////////

         float adjStart = start;
         float adjEnd = end;
         float adjFeather = feather/100.0;
         float rad = (90.0-anglee) * 0.0174533;
         vec2 v = normalize(vec2(cos(rad),-sin(rad)));
         float p = dot(acLayerNorm.st-vec2(0.5,0.5), v)+0.5;

         float p0 = smoothstepRev(adjStart-adjFeather,adjStart,p);
         float p1 = 1. - smoothstepRev(adjEnd,adjEnd+adjFeather,p);

 	vec4 fragColor;

     vec2 uv;
     uv = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     uv.y*=acLayerSize.y/acLayerSize.x;
     uv *= rot2m((0.0+anglee)*0.0174533);
     uv /= scalex;
         // vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

         float d = 1.0/abs(uv.y); //depth
         vec2 pv = vec2(uv.x*d, d); //perspective
         pv.y += autop? autor? xxa - (acTime*SPEED) : xxa + (acTime*SPEED) : xxa; //offset

             pv /= scale;
             pv *= rot2m((0.0+angle)*0.0174533);
             pv += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
             vec2 scaleVec;
             scaleVec = vec2(scale*stretch.x,scale*stretch.y);
             pv /= scaleVec;

         // my anti-aliasing attempt
         pv = abs((fract(pv)-0.5)*xxb); //grid vector
         float b = xxc/acScreenSize.y*d; //blur
         float t = xxd; //thickness
         float g = 1.0-smoothstep(t-b,t+b,pv.x)*smoothstep(t-b,t+b,pv.y); //grid

         vec3 col = vec3(g/d)*p0*p1;

         // vec3 cam = vec3(0.0, 2.0, 6.0);
         // cam.z -= xxa*5.0;
         // vec3 dir = normalize(vec3(uv, -1));
         // dir.yz *= rot2m(xxs);
         // dir.xz *= rot2m(xxt*0.1);

         // vec3 col = vec3(g/d);

         // fragColor = vec4(col*dir,1.0);
         fragColor = vec4(col,1.0);
         // vec4 factor = mix(texColorX,fragColor,1.0);

 	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         vec4 gradmap;
         float luminance = dot(fragColor.rgb, luminanceWeighting);
         gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    vec4 factor = mix(texColorX,gradmap,1.0);


     // float hardness = 1.0;
     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       // else if( blendMode==3 ) { factor *= hardness; 
         // resultfinal = (newLayer(texColor, (factor*hardnesss)) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
